insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MN', 'default', 'Нягтлан бодох бүртгэлийн дансны жагсаалт — аж ахуйн нэгж (Нягтлан бодох бүртгэлийн тухай хууль, Сангийн сайдын 347 дугаар тушаал)', '{"en":"Chart of accounts of business entities (Law on Accounting, Minister of Finance order No. 347 of 2017)"}'::jsonb, true, 'companies', array['MN-BS', 'MN-IS']::text[], null, 'Нягтлан бодох бүртгэлийн тухай хууль (2015) нь ерөнхий дэвтэр, дансны жагсаалтыг аж ахуйн нэгжид тогтоодог; Сангийн сайдын 2017 оны 347 дугаар тушаал нь маяг, зааврыг батална. Дансны жагсаалтын хавсралтын бүрэн эх нээлттэй эх сурвалжаас уншигдсангүй: ангилал (1 — эргэлтийн хөрөнгө … 7 — зардал) нь энэ багцын бүтэц бөгөөд хавсралтаас шууд хуулсан болохыг батлахгүй. README.md-г үз.', 'mof-order-347')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

