values
  ('MN', 'MN-P-10', 'НӨАТ 10 % — ерөнхий хувь (худалдан авалт)', '{"en":"VAT 10% — standard rate (purchase)"}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 14 дүгээр зүйлийн 14.1.1–14.1.2 — үйлдвэрлэл, үйлчилгээнд ашиглах бараа, ажил, үйлчилгээний НӨАТ-ыг суутгана; 14.5 — падаан дээр НӨАТ тусгагдсан байх ёстой; 14.6 — суутгахгүй зүйлс (суудлын автомашин, хувийн хэрэглээ, чөлөөлөгдсөн үйл ажиллагаа).', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('MN', 'MN-P-10-NR', 'НӨАТ 10 % — оршин суугч бус этгээдийн үйлчилгээ (худалдан авалт)', '{"en":"VAT 10% — services from a non-resident (recipient accounts for the tax)"}'::jsonb, 'Оршин суугч бус этгээдийн үйлчилгээний НӨАТ-ыг хүлээн авагч тооцож төсөвт төлж, төлсний дараа суутгана', 'percent', 10, 'purchase', 'foreign_services_received', date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 7 дугаар зүйлийн 7.2.5 — оршин суугч бус этгээдээс оршин суугчид борлуулсан бараа, ажил, үйлчилгээ татвар ногдуулах бүтээгдэхүүн; 16.1.2 — гаалийн мэдүүлэггүй худалдан авсан бараа, үйлчилгээний НӨАТ-ыг суутган төсөвт төлнө. Орчуулгад хэн суутгахыг тодорхойгүй тул (оршин суугч бус этгээд эсвэл хүлээн авагч) энэ кодыг хүлээн авагч суутгадаг гэж үзсэн; мэргэжилтэн баталгаажуулна (README.md). Тооцсон татвар 3433, суутгал 1543 дээр хүлээнэ.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('MN', 'MN-S-10', 'НӨАТ 10 % — ерөнхий хувь (борлуулалт)', '{"en":"VAT 10% — standard rate (sale)"}'::jsonb, null, 'percent', 10, 'sale', 'domestic', date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 11 дүгээр зүйлийн 11.1 — бараа, ажил, үйлчилгээний борлуулалтын үнэлгээнд 10 хувиар НӨАТ ногдуулна.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('MN', 'MN-S-EXEMPT-BANKING', 'НӨАТ-аас чөлөөлөгдсөн — банкны үйлчилгээ (борлуулалт)', '{"en":"VAT-exempt — banking services (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 13 дугаар зүйлийн 13.5.2 — банкны үйлчилгээг НӨАТ-аас чөлөөлнө.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('MN', 'MN-S-EXEMPT-RESIDENTIAL', 'НӨАТ-аас чөлөөлөгдсөн — орон сууцны байрны борлуулалт (борлуулалт)', '{"en":"VAT-exempt — sale of residential premises (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 13 дугаар зүйлийн 13.1.7 — орон сууцны байрны борлуулалтыг НӨАТ-аас чөлөөлнө (13.4: дахин борлуулах зорилгоор борлуулах шинээр баригдсан орон сууцыг эс оруулна).', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('MN', 'MN-S-ZERO-EXPORT', 'НӨАТ 0 % — барааны экспорт (борлуулалт)', '{"en":"VAT 0% — export of goods (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 12 дугаар зүйлийн 12.1.1 — гаалийн байгууллагад мэдүүлсэн экспортын бараа нь 0 хувийн татвартай.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('MN', 'MN-S-ZERO-TRANSPORT', 'НӨАТ 0 % — олон улсын тээвэр (борлуулалт)', '{"en":"VAT 0% — international transport (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 12 дугаар зүйлийн 12.1.2 — зорчигч, ачааны олон улсын тээвэр нь 0 хувийн татвартай.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null)
