  ('MN', 'MN-VAT', 'Нэмэгдсэн өртгийн албан татварын тайлан', array['month']::declaration_period[], 'month'::declaration_period, date '2016-01-01', null, 'НӨАТ-ын тухай хууль, 16 дугаар зүйл — НӨАТ суутган төлөгч татварыг улсын төсөвт төлж, тайланг баталсан маягтаар дараа сарын 10-ны дотор гаргана; тайлант хугацаа нь сар. Тайлангийн албан ёсны маягтын мөрийн дугаарыг нээлттэй эх сурвалжаас уншиж чадаагүй тул нүднүүдийг хуулийн зүйлээр (TAXABLE, ZERO, EXEMPT, TURNOVER, INPUT, CREDIT, PAYABLE, EXCESS) нэрлэсэн. README.md-г үз.', true,'day_of_month_after_period'::filing_deadline_rule, 10, null, 'НӨАТ-ын тухай хууль, 16 дугаар зүйлийн 16.1 — НӨАТ суутган төлөгч татварыг улсын төсөвт төлж, тайланг баталсан маягтаар дараа сарын 10-ны дотор гаргана. 2027 оны 1 дүгээр сарын 1-нээс хүчин төгөлдөр болохоор мэдээлэгдсэн НӨАТ-ын хуулийн нэмэлт, өөрчлөлт хугацааг ойролцоогоор 10 хоногоор уртасгана гэх мэдээлэл байгаа — эцсийн эх нийтлэгдсэний дараа энэ хугацааг шинэчилнэ (README.md).', 'vat-law', null)
